import itertools, random
from carbon_market.market import _optimize_batch

random.seed(42)

def brute(ordered, works, cand_lists, remaining):
    # cand_lists: job -> list of (slot, carbon_total, cost_total)
    best = None
    best_seq = None
    best_assign = None
    n = len(ordered)
    for choices in itertools.product(*[range(len(cand_lists[j]) + 1) for j in ordered]):
        caps = dict(remaining)
        work = count = carbon = cost = 0
        seq = []
        assign = {}
        ok = True
        for i, j in enumerate(ordered):
            c = choices[i]
            if c == len(cand_lists[j]):
                seq.append((1,))
                continue
            slot, cb, co = cand_lists[j][c]
            if caps.get(slot, 0) < works[j]:
                ok = False
                break
            caps[slot] -= works[j]
            work += works[j]; count += 1; carbon += cb; cost += co
            seq.append((0,) + slot)
            assign[j] = c
        if not ok:
            continue
        score = (work, count, -carbon, -cost)
        seq = tuple(seq)
        if best is None or score > best or (score == best and seq < best_seq):
            best, best_seq, best_assign = score, seq, dict(assign)
    return best_assign or {}

for trial in range(300):
    n = random.randint(1, 5)
    slots = [(f"r{k}", 1) for k in range(random.randint(1, 3))]
    ordered = sorted(f"j{i}" for i in range(n))
    works = {j: random.randint(1, 6) for j in ordered}
    accepted = {j: {"work": works[j]} for j in ordered}
    remaining = {s: random.randint(0, 12) for s in slots}
    cand_lists = {}
    candidate_map = {}
    for j in ordered:
        lst = []
        for s in slots:
            if random.random() < 0.7:
                carbon = random.randint(1, 5) * works[j]
                cost = random.randint(1, 5) * works[j]
                lst.append((s, carbon, cost))
        lst.sort(key=lambda x: (x[1], x[2], x[0][0]))
        cand_lists[j] = lst
        candidate_map[j] = [{"slot": s, "entry": {"total_carbon": cb, "total_cost": co}} for s, cb, co in lst]
    got = _optimize_batch(ordered, accepted, candidate_map, remaining)
    want = brute(ordered, works, cand_lists, remaining)
    got_simple = {j: v[0] for j, v in got.items()}
    if got_simple != want:
        print("MISMATCH", trial)
        print("works", works, "remaining", remaining)
        print("cands", cand_lists)
        print("got ", got_simple)
        print("want", want)
        break
else:
    print("all 300 randomized trials match brute force")
